from pathlib import Path
import json, subprocess
tid='DEV-PRED-ASTRA-RESULT-NORMALIZE-R6-20261008-N1E134'
homes=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
hits=[]
for base in homes:
    if base.exists():
        for p in base.rglob('*'):
            if tid in str(p) and p.is_file():
                try: txt=p.read_text(errors='replace')[:12000]
                except Exception as e: txt='READ_ERROR:'+type(e).__name__
                hits.append((str(p),txt))
wt=Path.home()/'.local/share/prediction-project-executor/worktrees'/tid
gitout=''
if wt.exists():
    for args in [['git','status','--short'],['git','log','-1','--oneline']]:
        try:
            r=subprocess.run(args,cwd=wt,capture_output=True,text=True,timeout=20)
            gitout += ' CMD='+' '.join(args)+' RC='+str(r.returncode)+' OUT='+(r.stdout+r.stderr).replace('\n',' ')[:2500]
        except Exception as e: gitout+=' GITERR='+type(e).__name__
def clean(s): return s.replace('\n',' ').replace('\r',' ').replace('|','/')
parts=[]
for p,txt in hits[:12]: parts.append('FILE='+clean(p)+' CONTENT='+clean(txt)[:2500])
parts.append('WORKTREE='+str(wt.exists())+clean(gitout))
print('ERROR_CLASS=N1E134_FORENSIC_STATE')
print('ERROR='+'|'.join(parts)[:12000])
raise SystemExit(1)
